from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    def max_depth(s: str, depth: int = 0, max_depth: int = 0) -> int:
        if not s:
            return max_depth
        if s[0] == '(':
            return max_depth_helper(s[1:], depth + 1, max(max_depth, depth))
        elif s[0] == ')':
            return max_depth_helper(s[1:], depth - 1, max_depth)
        else:
            return max_depth_helper(s[1:], depth, max_depth)

    def max_depth_helper(s: str, depth: int, max_depth: int) -> int:
        if not s:
            return max_depth
        if s[0] == '(':
            return max_depth_helper(s[1:], depth + 1, max(max_depth, depth))
        elif s[0] == ')':
            return max_depth_helper(s[1:], depth - 1, max_depth)
        else:
            return max_depth_helper(s[1:], depth, max_depth)

    groups = paren_string.split()
    results = []
    for group in groups:
        results.append(max_depth(group))
    return results

